-- ---------------------------------------------------------------------------
-- 167  Hyjal round-35 -- clone the border-zone quests
-- ---------------------------------------------------------------------------
-- Finishes what 166_ started.  166_ gave map 750 private copies of the stock
-- NPCs and objects (creature +3,700,000 / gameobject +3,900,000) but left the
-- quests shared, so the cloned NPCs offered nothing.  This clones the quests
-- too, at raw + 100,000.
--
--     194 quests, raw ids 28..13,075  ->  100,028..113,075
--
-- The window 100,000-199,999 was verified completely empty first: 175 quests
-- exist above 100,000, but every one is beyond 199,999 (up to 920,101).
--
-- CHAIN REMAPPING is the part that needs care.  PrevQuestID, NextQuestID,
-- ExclusiveGroup and BreadcrumbForQuestId each hold a quest id, and each is
-- rewritten ONLY when it points at a quest that is also in the cloned set:
--   * inside the set  -> +100,000, so the chain stays intact inside map 750
--   * outside the set -> LEFT RAW, because it points at a real prerequisite the
--     player earns elsewhere.  Blanking those would orphan chains; offsetting
--     them blindly would point at quests that do not exist.
--
-- ExclusiveGroup is the subtle one: it is a GROUP id (conventionally equal to
-- one member's quest id) whose SIGN carries meaning -- negative means "only one
-- of this group may be taken", positive means "all of them".  It is therefore
-- remapped by MAGNITUDE with the sign preserved.  Getting the sign wrong
-- inverts the rule for every quest in the group.
--
-- SOURCE SET is derived from the CLONED templates (entry - offset), not from
-- the spawn rows: 166_ already repointed those, so the raw ids are gone from
-- `creature`/`gameobject` and reading them would clone zero quests while
-- appearing to succeed.
--
-- quest_poi is rewritten to MapID 750 / WorldMapAreaId 1216 so the markers land
-- on the DC map.  The raw quests keep their own POI untouched.
--
-- Generated by HyjalCata/tools/gen_border_zone_quests.py.  Idempotent.
-- ---------------------------------------------------------------------------

-- --- quest_template ----------------------------------------------------------
DELETE FROM `quest_template` WHERE `ID` BETWEEN 100000 AND 199999;

-- SELECT * is safe here and preferable: quest_template has ~90 columns that
-- differ between forks, and only `ID` needs changing.  Every other clone block
-- in 166_/167_ uses an explicit list because it rewrites interior columns.
CREATE TEMPORARY TABLE `_qt_clone` AS SELECT * FROM `quest_template` WHERE `ID` IN (SELECT DISTINCT `quest` FROM `creature_queststarter` WHERE `id` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999)
  UNION SELECT DISTINCT `quest` FROM `creature_questender`   WHERE `id` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999)
  UNION SELECT DISTINCT `quest` FROM `gameobject_queststarter` WHERE `id` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000)
  UNION SELECT DISTINCT `quest` FROM `gameobject_questender`   WHERE `id` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000));
UPDATE `_qt_clone` SET `ID` = `ID` + 100000;
INSERT INTO `quest_template` SELECT * FROM `_qt_clone`;
DROP TEMPORARY TABLE `_qt_clone`;

-- Mail templates are ONE quest per template, first registration wins -- a clone
-- keeping the id either loses its own mail (cosmetic) or, when it registers
-- first, strips the mail reward from the STOCK quest (quest 5128 lost its
-- Everlook letter this way).  Clones reward without the follow-up mail.  The
-- mail fields live in quest_template_addon on this fork, and the column is
-- `RewardMailTemplateID` -- capital ID, unlike the worldserver's log message.
UPDATE `quest_template_addon` SET `RewardMailTemplateID` = 0, `RewardMailDelay` = 0
WHERE `ID` BETWEEN 100000 AND 199999 AND `RewardMailTemplateID` <> 0;

-- objectives that name a creature or object we cloned should point at the clone
UPDATE `quest_template` SET `RequiredNpcOrGo1` = `RequiredNpcOrGo1` + 3700000
WHERE `ID` BETWEEN 100000 AND 199999 AND `RequiredNpcOrGo1` > 0 AND `RequiredNpcOrGo1` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999);
UPDATE `quest_template` SET `RequiredNpcOrGo2` = `RequiredNpcOrGo2` + 3700000
WHERE `ID` BETWEEN 100000 AND 199999 AND `RequiredNpcOrGo2` > 0 AND `RequiredNpcOrGo2` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999);
UPDATE `quest_template` SET `RequiredNpcOrGo3` = `RequiredNpcOrGo3` + 3700000
WHERE `ID` BETWEEN 100000 AND 199999 AND `RequiredNpcOrGo3` > 0 AND `RequiredNpcOrGo3` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999);
UPDATE `quest_template` SET `RequiredNpcOrGo4` = `RequiredNpcOrGo4` + 3700000
WHERE `ID` BETWEEN 100000 AND 199999 AND `RequiredNpcOrGo4` > 0 AND `RequiredNpcOrGo4` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999);
-- a NEGATIVE RequiredNpcOrGo is a gameobject id, stored negated
UPDATE `quest_template` SET `RequiredNpcOrGo1` = `RequiredNpcOrGo1` - 3900000
WHERE `ID` BETWEEN 100000 AND 199999 AND `RequiredNpcOrGo1` < 0 AND -`RequiredNpcOrGo1` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000);
UPDATE `quest_template` SET `RequiredNpcOrGo2` = `RequiredNpcOrGo2` - 3900000
WHERE `ID` BETWEEN 100000 AND 199999 AND `RequiredNpcOrGo2` < 0 AND -`RequiredNpcOrGo2` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000);
UPDATE `quest_template` SET `RequiredNpcOrGo3` = `RequiredNpcOrGo3` - 3900000
WHERE `ID` BETWEEN 100000 AND 199999 AND `RequiredNpcOrGo3` < 0 AND -`RequiredNpcOrGo3` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000);
UPDATE `quest_template` SET `RequiredNpcOrGo4` = `RequiredNpcOrGo4` - 3900000
WHERE `ID` BETWEEN 100000 AND 199999 AND `RequiredNpcOrGo4` < 0 AND -`RequiredNpcOrGo4` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000);

-- --- quest_template_addon + chain remap --------------------------------------
DELETE FROM `quest_template_addon` WHERE `ID` BETWEEN 100000 AND 199999;
INSERT INTO `quest_template_addon` (`ID`, `MaxLevel`, `AllowableClasses`, `SourceSpellID`, `PrevQuestID`, `NextQuestID`, `ExclusiveGroup`, `BreadcrumbForQuestId`, `RewardMailTemplateID`, `RewardMailDelay`, `RequiredSkillID`, `RequiredSkillPoints`, `RequiredMinRepFaction`, `RequiredMaxRepFaction`, `RequiredMinRepValue`, `RequiredMaxRepValue`, `ProvidedItemCount`, `SpecialFlags`)
SELECT `ID` + 100000, `MaxLevel`, `AllowableClasses`, `SourceSpellID`, `PrevQuestID`, `NextQuestID`, `ExclusiveGroup`, `BreadcrumbForQuestId`, `RewardMailTemplateID`, `RewardMailDelay`, `RequiredSkillID`, `RequiredSkillPoints`, `RequiredMinRepFaction`, `RequiredMaxRepFaction`, `RequiredMinRepValue`, `RequiredMaxRepValue`, `ProvidedItemCount`, `SpecialFlags`
FROM `quest_template_addon` WHERE `ID` IN (SELECT DISTINCT `quest` FROM `creature_queststarter` WHERE `id` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999)
  UNION SELECT DISTINCT `quest` FROM `creature_questender`   WHERE `id` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999)
  UNION SELECT DISTINCT `quest` FROM `gameobject_queststarter` WHERE `id` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000)
  UNION SELECT DISTINCT `quest` FROM `gameobject_questender`   WHERE `id` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000));

-- Only rewrite a link when its target is also cloned; otherwise it names a real
-- prerequisite from elsewhere in the world and must stay raw.
UPDATE `quest_template_addon` SET `PrevQuestID` = `PrevQuestID` + 100000
WHERE `ID` BETWEEN 100000 AND 199999 AND `PrevQuestID` > 0 AND `PrevQuestID` IN (SELECT DISTINCT `quest` FROM `creature_queststarter` WHERE `id` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999)
  UNION SELECT DISTINCT `quest` FROM `creature_questender`   WHERE `id` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999)
  UNION SELECT DISTINCT `quest` FROM `gameobject_queststarter` WHERE `id` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000)
  UNION SELECT DISTINCT `quest` FROM `gameobject_questender`   WHERE `id` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000));
UPDATE `quest_template_addon` SET `PrevQuestID` = `PrevQuestID` - 100000
WHERE `ID` BETWEEN 100000 AND 199999 AND `PrevQuestID` < 0 AND -`PrevQuestID` IN (SELECT DISTINCT `quest` FROM `creature_queststarter` WHERE `id` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999)
  UNION SELECT DISTINCT `quest` FROM `creature_questender`   WHERE `id` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999)
  UNION SELECT DISTINCT `quest` FROM `gameobject_queststarter` WHERE `id` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000)
  UNION SELECT DISTINCT `quest` FROM `gameobject_questender`   WHERE `id` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000));
UPDATE `quest_template_addon` SET `NextQuestID` = `NextQuestID` + 100000
WHERE `ID` BETWEEN 100000 AND 199999 AND `NextQuestID` > 0 AND `NextQuestID` IN (SELECT DISTINCT `quest` FROM `creature_queststarter` WHERE `id` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999)
  UNION SELECT DISTINCT `quest` FROM `creature_questender`   WHERE `id` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999)
  UNION SELECT DISTINCT `quest` FROM `gameobject_queststarter` WHERE `id` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000)
  UNION SELECT DISTINCT `quest` FROM `gameobject_questender`   WHERE `id` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000));
UPDATE `quest_template_addon` SET `BreadcrumbForQuestId` = `BreadcrumbForQuestId` + 100000
WHERE `ID` BETWEEN 100000 AND 199999 AND `BreadcrumbForQuestId` > 0 AND `BreadcrumbForQuestId` IN (SELECT DISTINCT `quest` FROM `creature_queststarter` WHERE `id` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999)
  UNION SELECT DISTINCT `quest` FROM `creature_questender`   WHERE `id` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999)
  UNION SELECT DISTINCT `quest` FROM `gameobject_queststarter` WHERE `id` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000)
  UNION SELECT DISTINCT `quest` FROM `gameobject_questender`   WHERE `id` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000));

-- ExclusiveGroup: remap by MAGNITUDE, keep the SIGN.  Negative = "only one of
-- the group", positive = "all of them" -- flipping it would invert the rule.
UPDATE `quest_template_addon` SET `ExclusiveGroup` = `ExclusiveGroup` + 100000
WHERE `ID` BETWEEN 100000 AND 199999 AND `ExclusiveGroup` > 0 AND `ExclusiveGroup` IN (SELECT DISTINCT `quest` FROM `creature_queststarter` WHERE `id` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999)
  UNION SELECT DISTINCT `quest` FROM `creature_questender`   WHERE `id` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999)
  UNION SELECT DISTINCT `quest` FROM `gameobject_queststarter` WHERE `id` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000)
  UNION SELECT DISTINCT `quest` FROM `gameobject_questender`   WHERE `id` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000));
UPDATE `quest_template_addon` SET `ExclusiveGroup` = `ExclusiveGroup` - 100000
WHERE `ID` BETWEEN 100000 AND 199999 AND `ExclusiveGroup` < 0 AND -`ExclusiveGroup` IN (SELECT DISTINCT `quest` FROM `creature_queststarter` WHERE `id` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999)
  UNION SELECT DISTINCT `quest` FROM `creature_questender`   WHERE `id` IN (SELECT `entry` - 3700000 FROM `creature_template` WHERE `entry` BETWEEN 3700000 AND 3799999)
  UNION SELECT DISTINCT `quest` FROM `gameobject_queststarter` WHERE `id` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000)
  UNION SELECT DISTINCT `quest` FROM `gameobject_questender`   WHERE `id` IN (SELECT `entry` - 3900000 FROM `gameobject_template` WHERE `entry` >= 3900000));

